package com.smartgrocery.service; import com.smartgrocery.entity.*; import com.smartgrocery.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal; import java.util.*; @Service public class InventoryService { private final InventoryRepository inventory; private final ProductRepository products; public InventoryService(InventoryRepository i,ProductRepository p){inventory=i;products=p;} public List<Inventory> all(){return inventory.findAll();} @Transactional public Inventory adjust(Long productId,BigDecimal delta){Product p=products.findById(productId).orElseThrow(()->new NoSuchElementException("Product not found")); Inventory x=inventory.findByProductId(productId).orElseGet(()->new Inventory(p,BigDecimal.ZERO)); BigDecimal next=x.getPhysicalStock().add(delta); if(next.compareTo(x.getReservedStock())<0)throw new IllegalArgumentException("Adjustment would make available stock negative"); x.setPhysicalStock(next);return inventory.save(x);} }